const slugify=s=>s.toLowerCase().trim().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'');
function auth(){const n=am=='new';$('#root').innerHTML=`<main class="auth"><div class="in"><div class="logo">${brandHTML()}</div><h1>Run your whole club <span>from one screen.</span></h1><p class="mu" style="max-width:460px">Open-play queues, fair matching, live scoring and results. Built for pickleball clubs.</p><div class="court"><div class="ball"></div></div></div>
<div class="card in" style="--i:2;padding:22px"><div class="seg ${n?'':'r'}"><b></b><button class="${n?'on':''}" onclick="am='new';auth()">New Club</button><button class="${n?'':'on'}" onclick="am='old';auth()">Existing Club</button></div>
<h2 style="margin:18px 0 2px;font-size:22px">${n?'Create your club':'Welcome back'}</h2><p class="mu" style="margin:0">${cloudReady?(n?'Create an organizer account and sync your club online.':'Log in to manage your club from any device.'):(n?'Your club is stored in this browser only. Configure Supabase to sync across devices.':'Log in with your club link and password.')}</p>
${n?`<label for="an">Club Name</label><input id="an" placeholder="e.g., Sunday Open Play" oninput="if(!slugTouched)$('#as').value=slugify(this.value)"><div class="err" id="e-n"></div>
`:''}
${cloudReady?'<label for="ae">Organizer Email</label><input id="ae" type="email" autocomplete="email" placeholder="you@example.com"><div class="err" id="e-e"></div>':''}
${cloudReady&&!n?'':`<label for="as">Club Link</label><div class="hint">${cloudReady?'This will be part of your player queue link.':'Staff use this to log in.'}</div><div class="slug"><span class="mono">#club-</span><input id="as" class="mono" placeholder="your-club" oninput="slugTouched=true"></div><div class="err" id="e-s"></div>`}
<label for="ap">${cloudReady?'Password':'Club Password'}</label><input id="ap" type="password" autocomplete="${n?'new-password':'current-password'}" placeholder="${n?'Create a password (8+ characters)':'Enter your password'}" onkeydown="if(event.key=='Enter')go()"><div class="err" id="e-p"></div>
<button class="btn" style="width:100%;margin-top:4px" onclick="go()">${n?'Create club':'Log in'}</button>
<div class="row" style="margin-top:14px;font-size:13px"><button class="btn g sm" onclick="enterDemo()">Try the demo</button><span class="sp"></span>${n?'':'<button style="background:none;border:0;color:var(--ac)" onclick="forgot()">Forgot password?</button>'}</div><div class="row" style="margin-top:6px;justify-content:center"><button class="lnk" onclick="privacyM()">Privacy</button><span class="mu">·</span><button class="lnk" onclick="helpM()">Help</button></div></div></main>`}
function fe(id,m){$('#e-'+id).textContent=m||'';return !m}
async function go(){const n=am=='new',s=slugify($('#as')?.value||''),p=$('#ap').value;let ok=true;
if(cloudReady){
 const email=$('#ae').value.trim().toLowerCase();
 ok=fe('e',/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)?'':'Enter a valid organizer email.')&ok;
 if(n){const nm=$('#an').value.trim();ok=fe('n',nm?'':'Enter a club name.')&ok;ok=fe('s',s.length<3?'Use at least 3 letters or numbers.':'')&ok}
 ok=fe('p',p.length>=8?'':'Use at least 8 characters.')&ok;if(!ok)return;
 const nm=n?$('#an').value.trim():'';
 const result=n?await cloud.auth.signUp({email,password:p,options:{data:{club_name:nm,club_slug:s}}}):await cloud.auth.signInWithPassword({email,password:p});
 if(result.error){fe('p',result.error.message);return}
 if(!result.data.session){toast('Check your email to confirm, then log in.',5000);am='old';auth();return}
 cloudUser=result.data.user;
 if(n){const {data:existing}=await cloud.from('club_accounts').select('id').eq('slug',s).maybeSingle();if(existing){await cloud.auth.signOut();cloudUser=null;fe('s','That club link is already in use.');return}
 const {data:club,error}=await cloud.from('club_accounts').insert({owner_id:cloudUser.id,slug:s,name:nm}).select().single();
 if(error){fe('s',error.message);return}cloudClub=club;
 const old=ls.get('sq_state_'+s);if(old){await cloud.from('club_data').upsert({club_id:club.id,payload:{state:old,history:ls.get('sq_hist_'+s)||[],life:ls.get('sq_life_'+s)||{}}})}
 } else {let {data:club,error}=await cloud.from('club_accounts').select('*').eq('owner_id',cloudUser.id).maybeSingle();
 if(!error&&!club&&cloudUser.user_metadata?.club_slug){const meta=cloudUser.user_metadata;const created=await cloud.from('club_accounts').insert({owner_id:cloudUser.id,slug:meta.club_slug,name:meta.club_name||meta.club_slug}).select().single();club=created.data;error=created.error}
 if(error||!club){fe('e',error?.message||'No club is linked to this organizer account.');return}cloudClub=club}
 me=cloudClub.slug;clubs[me]={name:cloudClub.name};await cloudLoad();app();toast(n?'Club created and synced.':'Welcome back!');firstRun();return;
}
if(n){const nm=$('#an').value.trim();
ok=fe('n',nm?'':'Enter a club name.')&ok;
const taken=!!clubs[s];
ok=fe('s',s.length<3?'Use at least 3 letters or numbers.':taken?'That link is taken. Try another.':'')&ok;ok=fe('p',p.length>=8?'':'Use at least 8 characters.')&ok;
if(!ok)return;const salt=rnd();clubs[s]={name:nm,email:'',h:await hashPw(p,salt),salt,alg:'p2'};ls.set('sq_clubs',clubs);enter(s,'Club created. Let’s play!')}
else{
ok=fe('s',clubs[s]?'':'We can’t find that club link.')&ok;ok=fe('p',p?'':'Enter your password.')&ok;if(!ok)return;
if(!(await pwOk(clubs[s],p)))return fe('p','Wrong password. Try again.');
if(clubs[s].alg!=='p2'){const salt=rnd();clubs[s].salt=salt;clubs[s].h=await hashPw(p,salt);clubs[s].alg='p2';ls.set('sq_clubs',clubs)}
enter(s,'Welcome back!')}}
function forgot(){M('Forgot your password?','<p class="mu" style="margin:8px 0 14px;font-size:14px">Your club is saved only in this browser, so a reset link can’t be emailed. You can create a new club, or restore a backup you downloaded earlier.</p><button class="btn" onclick="closeM()">OK</button>')}
function enter(s,m){me=s;ls.set('sq_me',s);tab='Queue';loadState(s);app();toast(m||'Welcome');firstRun()}
async function out(){S.ov=null;try{renderOv();closeM()}catch(e){}if(cloudReady){if(adminChannel)await cloud.removeChannel(adminChannel);adminChannel=null;await cloud.auth.signOut();cloudUser=null;cloudClub=null;me=null;auth();return}me=null;ls.set('sq_me',null);auth()}
// ---------- game logic ----------
const TABS=['Queue','Players','History'];let tab='Queue';
const MODES={Balanced:['Balances teams by rating. Avoids repeat matchups.','Recommended'],'Social Mix':['Rotates partners and opponents. Ratings aren’t used.','Improved'],'Skill Separated':['Keeps similar skill levels together.',''],'Winners / Losers':['Winners play winners, losers play losers.','']};
let S={mode:'Balanced',nc:2,id:0,pl:[],courts:[],un:[],phase:'setup',name:'Open Play',q:'',sound:true,t0:0,seq:0,ov:null,shuf:false,_k:''};
const nowS=()=>Date.now()+(S.seq++)/1000;
function add(n,r,i){n=String(n).replace(/[<>&"`\\]/g,'').replace(/'/g,'’').trim();const p={id:S.id++,n,r:Math.min(5,Math.max(0,Math.round(+r)||0)),st:i?'in':'out',g:0,w:0,l:0,s:0,since:i?nowS():0,last:'',pr:null,pf:0,pa:0,run:0,inAt:i?Date.now():0,outAt:0};S.pl.push(p);if(i)setFb(p);return p}
const B_=i=>S.pl.find(p=>p.id===i),q=()=>S.pl.filter(p=>p.st==='in').sort((a,b)=>a.since-b.since);
const hue=n=>[...n].reduce((a,c)=>a+c.charCodeAt(0)*37,0)%360,av=p=>`<div class="av" style="background:hsl(${hue(p.n)} 55% 34%)">${p.n.slice(0,2).toUpperCase()}</div>`;
const tm=t=>{const s=Math.max(0,Math.floor((Date.now()-t)/1e3));return Math.floor(s/60)+':'+String(s%60).padStart(2,'0')};
const LV=['Unrated','Beginner','Novice','Intermediate','Advanced','Pro'];
const st=(r,id)=>`<span class="stars" title="${LV[r]}">${[1,2,3,4,5].map(n=>id==null?`<i class="${n<=r?'on':''}">★</i>`:`<button class="sb ${n<=r?'on':''}" aria-label="${n} star${n>1?'s':''}, ${LV[n]}" title="${LV[n]}" onclick="setR(${id},${n})">★</button>`).join('')}</span>`;
function setR(i,n){B_(i).r=n;draw();toast(B_(i).n+': '+LV[n])}
const lp=p=>p.pr!=null?`<span class="pill ac" style="margin-left:6px">🔒 ${B_(p.pr).n}</span>`:'';
function checkIn(i){const p=B_(i);p.st='in';p.since=nowS();if(!p.inAt)p.inAt=Date.now();p.outAt=0;setFb(p)}
function delP(i){const p=B_(i);if(!p||p.st=='play')return;const idx=S.pl.indexOf(p);S.pl.splice(idx,1);S.pl.forEach(x=>{if(x.pr===i)x.pr=null});S.rm={p,idx};draw()}
function undoRm(){const r=S.rm;if(!r)return;S.pl.splice(Math.min(r.idx,S.pl.length),0,r.p);const o=B_(r.p.pr);if(o&&o.pr==null)o.pr=r.p.id;else r.p.pr=null;S.rm=null;draw();toast(r.p.n+' restored')}
function sync(){if(S.courts.length>S.nc)S.courts.length=S.nc;while(S.courts.length<S.nc)S.courts.push({m:null})}
function fill(){if(S.phase=='live')ux()}
function units(ex){const w=q().filter(p=>!ex||!ex.has(p.id)),seen=new Set(),U=[];for(const p of w){if(seen.has(p.id))continue;if(p.pr!=null&&SZ()==2){const m=B_(p.pr);if(m.st!='in'||(ex&&ex.has(m.id)))continue;seen.add(m.id);U.push([p,m])}else U.push([p]);seen.add(p.id)}return U}
const avg=(u,k)=>u.reduce((a,p)=>a+(k=='r'?(p.r||3):p[k]),0)/u.length;
const rv=p=>p.r||3,tot=a=>a.reduce((t,i)=>t+rv(B_(i)),0);
const kk=(x,y)=>x<y?x+'-'+y:y+'-'+x,bump=(o,x,y)=>{o[kk(x,y)]=(o[kk(x,y)]||0)+1};
function recM(m){S.pc=S.pc||{};S.oc=S.oc||{};[m.a,m.b].forEach(t=>{if(t.length>1)bump(S.pc,t[0],t[1])});m.a.forEach(x=>m.b.forEach(y=>bump(S.oc,x,y)))}
function reps(a,b){let pw=0,ow=0;[a,b].forEach(t=>{if(t[0]!=null&&t[1]!=null&&B_(t[0]).pr!==t[1])pw+=(S.pc||{})[kk(t[0],t[1])]||0});a.forEach(x=>b.forEach(y=>{ow+=(S.oc||{})[kk(x,y)]||0}));return{pw,ow}}
function repNote(m){const r=reps(m.a,m.b);return r.pw?' · <span class="am">repeat partners</span>':r.ow?' · <span class="am">repeat opponents</span>':' · <span class="ac">new matchup</span>'}
const eg=p=>p.g+(p.fb||0);
function setFb(p){p.fb=0}
const SZ=()=>S.size||2,NP=()=>SZ()*2,dd=p=>(p.pf||0)-(p.pa||0),dfx=p=>{const d=dd(p);return(d>0?'+':'')+d};
const capped=p=>S.maxRun>0&&(p.run||0)>=S.maxRun;
function markRun(m){const ids=new Set([...m.a,...m.b]);S.pl.forEach(p=>{if(ids.has(p.id))p.run=(p.run||0)+1;else if(p.st=='in')p.run=0})}
function noteWL(m){const ids=[...m.a,...m.b].map(i=>B_(i).last),w=ids.filter(x=>x=='w').length,l=ids.filter(x=>x=='l').length;S.wlNext=w>l?'l':l>w?'w':S.wlNext}
function smartPick(U){const N=NP(),P0=U.filter(u=>!u.some(capped)),V=P0.reduce((t,u)=>t+u.length,0)>=N?P0:U;return smartCore(V,U,N)||(V!==U?smartCore(U,U,N):null)}
function smartCore(V,U,N){
const gu=u=>Math.max(...u.map(eg)),ix=new Map(U.map((u,i)=>[u,i])),S1=[...V].sort((a,b)=>gu(a)-gu(b)||ix.get(a)-ix.get(b));
let n=0,G=0;const acc=[];for(const u of S1){if(n+u.length<=N){acc.push(u);n+=u.length;G=gu(u);if(n==N)break}}
if(n<N)return null;
const mand=acc.filter(u=>gu(u)<G),need=N-mand.reduce((t,u)=>t+u.length,0);
const build=opt=>{const C=[];const rec=(i,cur,k)=>{if(k==need){C.push(cur);return}if(i>=opt.length)return;if(k+opt[i].length<=need)rec(i+1,[...cur,opt[i]],k+opt[i].length);rec(i+1,cur,k)};rec(0,[],0);return C};
let C=build(S1.filter(u=>gu(u)===G).slice(0,10));
if(!C.length)C=build(S1.filter(u=>!mand.includes(u)).slice(0,12));
if(!C.length)return null;
const O=[],md=S.mode;
C.forEach(ch=>{const us=[...mand,...ch],pos=us.reduce((t,u)=>t+ix.get(u)*u.length,0),pr=us.filter(u=>u.length==2),sg=us.filter(u=>u.length==1).map(u=>u[0]),T=[];
if(N==2)T.push([[sg[0]],[sg[1]]]);else if(pr.length==2)T.push([pr[0],pr[1]]);else if(pr.length==1)T.push([pr[0],sg]);else T.push([[sg[0],sg[1]],[sg[2],sg[3]]],[[sg[0],sg[2]],[sg[1],sg[3]]],[[sg[0],sg[3]],[sg[1],sg[2]]]);
const all=us.flat(),rs=all.map(rv),spread=Math.max(...rs)-Math.min(...rs),nw=all.filter(p=>p.last=='w').length,nl=all.filter(p=>p.last=='l').length,mis=Math.min(nw,nl),wrong=(S.wlNext=='w'&&nl>nw)||(S.wlNext=='l'&&nw>nl)?1:0;
T.forEach(t=>{const d=Math.abs(t[0].reduce((x,p)=>x+rv(p),0)-t[1].reduce((x,p)=>x+rv(p),0)),r=reps(t[0].map(p=>p.id),t[1].map(p=>p.id));let cost;
if(md=='Social Mix')cost=r.pw*100+r.ow*40+pos;
else if(md=='Skill Separated')cost=spread*100+d*30+r.pw*10+r.ow*4+pos;
else if(md=='Winners / Losers')cost=mis*100+wrong*40+d*10+r.pw*10+r.ow*4+pos;
else cost=d*100+r.pw*25+r.ow*8+Math.abs(Math.max(...t[0].map(rv))-Math.max(...t[1].map(rv)))*3+pos;
O.push({a:t[0].map(p=>p.id),b:t[1].map(p=>p.id),cost})})});
O.sort((x,y)=>x.cost-y.cost);const o=S.shuf?O[Math.floor(Math.random()*Math.min(3,O.length))]:O[0];return{a:o.a,b:o.b}}
function pick(ex){const U=units(ex);return U.length?smartPick(U):null}
function lock(a,b){[a,b].forEach(i=>{const p=B_(i);if(p.pr!=null)B_(p.pr).pr=null});const A=B_(a),Z=B_(b);A.pr=b;Z.pr=a;A.since=Z.since=Math.min(A.since,Z.since);S.nx=null;fill();draw();toast(A.n+' & '+Z.n+' are locked in')}
function unlock(i){const p=B_(i),o=B_(p.pr);p.pr=null;o.pr=null;S.nx=null;fill();draw();toast('Unlocked')}
function doLock(){const a=+$('#l1').value,b=+$('#l2').value;if(a==b)return toast('Pick two different players');lock(a,b)}
function lockCard(){const prs=S.pl.filter(p=>p.pr!=null&&p.id<p.pr),fr=S.pl.filter(p=>p.pr==null);const o=fr.map((p,i)=>`<option value="${p.id}">${p.n}</option>`).join(''),o2=fr.map((p,i)=>`<option value="${p.id}" ${i==1?'selected':''}>${p.n}</option>`).join('');
return `<div class="card in" style="--i:3"><h3>Lock in partners</h3><p class="mu" style="margin:0 0 10px;font-size:13px">Locked players queue as a team and always play on the same side. If one partner rests, the other waits.</p>${prs.map(p=>`<div class="pl"><b>🔒 ${p.n} & ${B_(p.pr).n}</b><span class="sp"></span><button class="btn g sm" onclick="unlock(${p.id})">Unlock</button></div>`).join('')}${fr.length<2?'':`<div class="row" style="flex-wrap:nowrap;margin-top:10px"><select id="l1" aria-label="First player">${o}</select><select id="l2" aria-label="Second player">${o2}</select><button class="btn" onclick="doLock()">Lock</button></div>`}</div>`}
function standings(){const rk=p=>p.g>=3,wr=p=>p.g?p.w/p.g:0;const L=[...S.pl].sort((a,b)=>(rk(b)-rk(a))||wr(b)-wr(a)||b.w-a.w||dd(b)-dd(a)||b.g-a.g);let n=0;return `<div class="card in" style="margin-top:16px;--i:3"><div class="row" style="margin-bottom:8px"><h3 style="margin:0">Current standings</h3><span class="sp"></span><span class="mu" style="font-size:12px">Ranked after 3 matches</span></div><div class="scroll"><table><thead><tr><th>#</th><th>Player</th><th>Status</th><th>Matches</th><th>Won</th><th>Lost</th><th>Win rate</th><th>Streak</th>${S.scores?'<th>+/-</th>':''}</tr></thead><tbody>${L.map((p,i)=>`<tr style="animation-delay:${i*30}ms"><td class="mono">${rk(p)?++n:'—'}</td><td><div class="row">${av(p)}<b>${p.n}</b></div></td><td><span class="pill">${{in:'Queued',play:'Playing',out:'Not here',rest:'Resting'}[p.st]}</span></td><td class="mono">${p.g}</td><td class="mono">${p.w}</td><td class="mono">${p.l}</td><td><div class="row" style="flex-wrap:nowrap"><span class="mono" style="width:40px">${p.g?Math.round(wr(p)*100)+'%':'—'}</span><div style="flex:1;min-width:60px;height:6px;border-radius:9px;background:var(--s2)"><i style="display:block;height:100%;width:${wr(p)*100}%;border-radius:9px;background:var(--ac);transition:width .8s var(--e)"></i></div></div></td><td class="mono ${p.s>0?'ac':p.s<0?'am':'mu'}">${p.s>0?'W'+p.s:p.s<0?'L'+(-p.s):'—'}</td>${S.scores?`<td class="mono">${dfx(p)}</td>`:''}</tr>`).join('')}</tbody></table></div></div>`}
// ---------- session flow ----------
function ux(force,only){const ok=m=>m&&[...m.a,...m.b].every(i=>B_(i).st=='in'),used=new Set();
S.un.forEach((s,k)=>{if(s.m&&!ok(s.m)){s.m=null;s.pin=false}if(((force===true||force==='fresh')&&!s.pin)||only===k){s.m=null;s.pin=false}if(s.m)[...s.m.a,...s.m.b].forEach(i=>used.add(i))});
S.shuf=force===true||force===1;S.un.forEach(s=>{if(!s.m){const m=pick(used);if(m){s.m=m;[...m.a,...m.b].forEach(i=>used.add(i))}}});S.shuf=false}
function startS(){if(q().length<NP())return;S.rm=null;S.pc={};S.oc={};S.mn=0;S.log=[];S.pl.forEach(p=>{p.g=p.w=p.l=p.s=0;p.fb=0;p.run=0;p.pf=0;p.pa=0;p.last=''});S.phase='live';S.t0=Date.now();sync();S.un=[{m:null,pin:false}];tab='Queue';draw();toast('Session started. Courts are ready!');maybeTour()}
