function qrM(){const u=baseUrl()+'#kiosk';M('Player check-in QR','<p class="mu" style="margin:6px 0 12px">Scanning opens the check-in screen. It works in this browser, on a device that already has this club. Letting players check in from their own phones would need an online service that this version doesn’t include.</p><div id="qr" style="background:#fff;padding:12px;border-radius:14px;width:fit-content;margin:auto"></div><p class="mono" style="font-size:12px;text-align:center">'+u+'</p><button class="btn" style="width:100%" onclick="closeM();S.ov=\'kiosk\';draw()">Open kiosk mode</button><p class="mu" style="font-size:12px;margin-bottom:0">Tip: open kiosk mode on a shared tablet by the courts.</p>');try{const q=qrcode(0,'M');q.addData(u);q.make();$('#qr').innerHTML=q.createSvgTag({cellSize:4,margin:0,scalable:true});const sv=$('#qr svg');sv.setAttribute('width','180');sv.setAttribute('height','180');sv.setAttribute('role','img');sv.setAttribute('aria-label','QR code for the check-in screen')}catch(e){$('#qr').remove()}}
