S.rep={id:end,name:S.name,scores:!!S.scores,games:g,mins:Math.max(1,Math.round((end-S.t0)/60000)),courts:S.courts.length,end,std,part:[...P].sort((a,b)=>a.g-b.g||a.n.localeCompare(b.n))};
