function blip(f,d,t){if(!S.sound)return;try{const A=ac(),o=A.createOscillator(),g=A.createGain(),n=A.currentTime;o.type=t||'triangle';o.frequency.value=f;g.gain.setValueAtTime(.0001,n);g.gain.exponentialRampToValueAtTime(.1,n+.015);g.gain.exponentialRampToValueAtTime(.0001,n+d);o.connect(g);g.connect(A.destination);o.start();o.stop(n+d+.02)}catch(e){}}
