recM(m);[...m.a,...m.b].forEach((i,k)=>{const p=B_(i),isA=k<m.a.length,w=isA==(win=='a');p.g++;w?p.w++:p.l++;if(hs){p.pf=(p.pf||0)+(isA?sa:sb);p.pa=(p.pa||0)+(isA?sb:sa)}p.s=w?(p.s>0?p.s+1:1):(p.s<0?p.s-1:-1);p.last=w?'w':'l';p.st='in';p.since=nowS()});
