function scAdj(ci,t,d){const m=S.courts[ci]&&S.courts[ci].m;if(!m)return;m['s'+t]=Math.max(0,(m['s'+t]||0)+d);const w=reached(m);if(w&&!m.cf){m.cf=1;toast('Team '+w.toUpperCase()+' reached '+(S.to||11)+'. Confirm the result to finish')}if(!w)m.cf=0;draw()}
