function lifeAdd(R){const L=scrub(ls.get('sq_life_'+me)||{});R.part.forEach(p=>{if(!p.g)return;const k=p.n.toLowerCase(),x=L[k]||(L[k]={n:p.n,g:0,w:0,l:0,pf:0,pa:0,ss:0});x.n=p.n;x.r=p.r;x.g+=p.g;x.w+=p.w;x.l+=p.l;x.pf+=p.pf||0;x.pa+=p.pa||0;x.ss++;x.last=R.end});ls.set('sq_life_'+me,L)}
const wrOf=x=>x&&x.g?x.w/x.g:0,pst=(v,l,c)=>`<div class="pst ${c||''}"><b class="mono">${v}</b><small>${l}</small></div>`,STL={in:'Queued',play:'Playing',rest:'Resting',out:'Not here'};
function pRows(){const L=scrub(ls.get('sq_life_'+me)||{}),have=new Set(S.pl.map(p=>p.n.toLowerCase())),nm=r=>r.p?r.p.n:r.x.n;
let R=[...S.pl.map(p=>({p,x:L[p.n.toLowerCase()]||{g:0,w:0,l:0,pf:0,pa:0,ss:0}})),...Object.entries(L).filter(([k])=>!have.has(k)).map(([k,x])=>({p:null,x}))].filter(r=>nm(r).toLowerCase().includes((PS.q||'').toLowerCase()));
const key={matches:r=>-r.x.g,wins:r=>-r.x.w,rate:r=>r.x.g>=5?-wrOf(r.x):1};
R.sort(PS.sort=='name'?(a,b)=>nm(a).localeCompare(nm(b)):(a,b)=>key[PS.sort](a)-key[PS.sort](b)||b.x.g-a.x.g||nm(a).localeCompare(nm(b)));return R}
function pList(){const R=pRows();if(!R.length)return `<p class="mu" style="margin:14px 0 0">${S.pl.length||Object.keys(scrub(ls.get('sq_life_'+me)||{})).length?'No players match that search.':'No players yet. Add players on the Queue page. Their all-time stats build up as you finish sessions.'}</p>`;
return R.map(({p,x})=>{const wr=wrOf(x),pm=(x.pf||0)+(x.pa||0)>0,sg=p&&x.g>=10&&wr>=.65&&p.r>0&&p.r<5?p.r+1:p&&x.g>=10&&wr<=.3&&p.r>1?p.r-1:p&&!p.r&&x.g>=5?3:0;
return `<div class="prow"><button class="pbtn" onclick="${p?`plM(${p.id})`:`plM(-1,'${x.n.replace(/'/g,'’')}')`}">${av(p||{n:x.n})}<span class="pi2"><b>${p?p.n:x.n}</b><span class="mu" style="font-size:12px">${p?STL[p.st]:'Not on roster'}${x.ss?' · '+x.ss+' session'+(x.ss==1?'':'s'):''}</span></span></button><div class="pr">${st(p?p.r:x.r||0,p?p.id:null)}</div><span class="sp"></span>${pst(x.g,'MATCHES')}${pst(x.w,'WON')}${pst(x.g?Math.round(wr*100)+'%':'—','WIN RATE','ac')}${pm?pst(dfx(x),'+/-'):''}<span class="psg">${sg?`<button class="btn sm" onclick="setR(${p.id},${sg})">Suggest ★${sg}</button>`:''}${p?'':`<button class="btn g sm" onclick="addRos('${x.n.replace(/'/g,'’')}')">Add to roster</button>`}</span></div>`}).join('')}
