top=[['Most wins',best(x=>x.w,1),x=>x.w+' wins'],['Best win rate (5+ matches)',best(wrOf,5),x=>Math.round(wrOf(x)*100)+'%'],['Most matches',best(x=>x.g,1),x=>x.g+' matches']];
