function migrate(o){if(!o||typeof o!=='object')return o;o=JSON.parse(JSON.stringify(o));
o.pl=(Array.isArray(o.pl)?o.pl:[]).filter(p=>p&&typeof p.id==='number'&&typeof p.n==='string').map(p=>({g:0,w:0,l:0,s:0,pf:0,pa:0,run:0,fb:0,last:'',pr:null,inAt:0,outAt:0,since:0,r:0,st:'out',...p}));
['courts','un','log'].forEach(k=>{if(!Array.isArray(o[k]))o[k]=[]});o.pc=o.pc&&typeof o.pc==='object'?o.pc:{};o.oc=o.oc&&typeof o.oc==='object'?o.oc:{};
const ids=new Set(o.pl.map(p=>p.id)),okm=m=>m&&Array.isArray(m.a)&&Array.isArray(m.b)&&[...m.a,...m.b].every(i=>ids.has(i));
o.id=Math.max(o.id||0,0,...o.pl.map(p=>p.id+1));
o.courts=o.courts.map(c=>({m:c&&okm(c.m)?c.m:null}));o.un=o.un.map(u=>({m:u&&okm(u.m)?u.m:null,pin:!!(u&&u.pin&&okm(u.m))}));
const inPlay=new Set();o.courts.forEach(c=>{if(c.m)[...c.m.a,...c.m.b].forEach(i=>inPlay.add(i))});
o.pl.forEach(p=>{if(p.pr!=null&&!ids.has(p.pr))p.pr=null;if(!['in','play','rest','out'].includes(p.st))p.st='out';if(p.st=='play'&&!inPlay.has(p.id))p.st='in'});
if(!['setup','live','done'].includes(o.phase))o.phase='setup';o._v=DATA_V;return o}
