function tourPos(){if(!TR)return;const p=TOURS[TR.k][TR.i],el=document.querySelector(p.sel),sp=document.querySelector('#tour .tspot'),pp=document.querySelector('#tour .tpop');if(!el||!sp||!pp)return;const r=el.getBoundingClientRect(),pad=8,pw=Math.min(340,innerWidth-24);sp.style.cssText=`left:${r.left-pad}px;top:${r.top-pad}px;width:${r.width+pad*2}px;height:${r.height+pad*2}px`;pp.style.width=pw+'px';const ph=pp.offsetHeight;let top=r.bottom+pad+12;if(top+ph>innerHeight-12)top=Math.max(12,r.top-pad-12-ph);pp.style.top=top+'px';pp.style.left=Math.min(Math.max(12,r.left),innerWidth-pw-12)+'px'}
