const live=S.phase=='live';if(live)ux();
{const t=$('#ttl');t.textContent=tab=='History'?'History':tab=='Players'?'Players':live?S.name:S.phase=='done'?'Session complete':'Queue setup';const c=document.createElement('span');c.className='ttl-c';c.textContent=' · '+clubs[me].name;t.appendChild(c)}
